import React from "react";
import { Flex, Text, TooltipComponent } from "../../atoms";
import { CSS } from "../../../stitches.config";

export type SelectorOption<T = string> = {
  value: T;
  label: string;
  tooltip?: string;
  tooltipTitle?: string;
  tooltipDescription?: string;
  css?: CSS;
};

export type SelectorProps<T = string> = {
  selectedValue: T;
  onValueChange: (value: T) => void;
  options: SelectorOption<T>[];
  css?: CSS;
  itemWidth?: string | number;
  tooltipSide?: "top" | "bottom" | "left" | "right";
  tooltipAvoidCollisions?: boolean;
};

export const Selector = <T extends string | number = string>({
  selectedValue,
  onValueChange,
  options,
  css,
  itemWidth = "34px",
  tooltipSide = "bottom",
  tooltipAvoidCollisions = true,
}: SelectorProps<T>) => {
  return (
    <Flex
      css={{
        alignItems: "center",
        gap: 0,
        border: "1px solid $bg05",
        borderRadius: "$3",
        backgroundColor: "$bg02",
        width: "fit-content",
        ...css,
      }}
    >
      {options.map((option, index) => {
        const isSelected = option.value === selectedValue;

        // Determine tooltip content
        const tooltipContent =
          option.tooltipTitle && option.tooltipDescription ? (
            <Flex css={{ flexDirection: "column", gap: "$xxxs" }}>
              <Text css={{ fontWeight: "$bold", fontSize: "$2", color: "$muted" }}>
                {option.tooltipTitle}
              </Text>
              <Text css={{ fontSize: "$2", color: "$muted" }}>
                {option.tooltipDescription}
              </Text>
            </Flex>
          ) : (
            option.tooltip
          );

        return (
          <Flex key={String(option.value)} css={{ alignItems: "center" }}>
            <TooltipComponent
              content={tooltipContent}
              side={tooltipSide}
              avoidCollisions={tooltipAvoidCollisions}
              css={{ zIndex: 1000 }}
            >
              <Flex
                onClick={() => onValueChange(option.value)}
                css={{
                  cursor: "pointer",
                  padding: "4px 0",
                  backgroundColor: isSelected ? "$bg04" : "transparent",
                  userSelect: "none",
                  width: itemWidth,
                  justifyContent: "center",
                  alignItems: "center",
                  ...(index === 0
                    ? {
                        borderTopLeftRadius: "$3",
                        borderBottomLeftRadius: "$3",
                      }
                    : {}),
                  ...(index === options.length - 1
                    ? {
                        borderTopRightRadius: "$3",
                        borderBottomRightRadius: "$3",
                      }
                    : {}),
                  ...(index > 0 ? { borderLeft: "1px solid $bg05" } : {}),
                  "&:hover": {
                    backgroundColor: isSelected ? "$bg04" : "$bg03",
                  },
                  ...option.css,
                }}
              >
                <Text
                  css={{
                    fontSize: "$4",
                    fontWeight: "$normal",
                    color: isSelected ? "$light" : "$muted",
                    lineHeight: "1",
                  }}
                >
                  {option.label}
                </Text>
              </Flex>
            </TooltipComponent>
          </Flex>
        );
      })}
    </Flex>
  );
};

Selector.displayName = "Selector";
